-- +goose Up

-- Uploaded and generated files (backend plan section 13). The blob lives in
-- storage under `key`; image variants (thumb, medium) are separate blobs named
-- key || '.' || variant and described in `variants`.
CREATE TABLE file (
    id             uuid        PRIMARY KEY,
    org_id         uuid        NOT NULL REFERENCES organization (id),
    -- uuid without a foreign key until the sites table exists (phase B adds it)
    site_id        uuid,
    key            text        NOT NULL,
    -- sanitized file name as uploaded (personal data: hashed in audit diffs)
    name           text        NOT NULL,
    size           bigint      NOT NULL DEFAULT 0 CHECK (size >= 0),
    mime           text        NOT NULL,
    sha256         text        CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    -- a user that is erased leaves the file behind without an uploader
    uploaded_by    uuid        REFERENCES "user" (id) ON DELETE SET NULL,
    -- the resource the file is attached to, resolved by the owning module's visibility resolver
    scope_type     text,
    scope_id       uuid,
    -- pending: being stored or scanned; ready; quarantined: the virus scan flagged it;
    -- deleted: removed by a user or by retention, blobs await purge
    status         text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'ready', 'quarantined', 'deleted')),
    -- uploaded by a person, or generated by the server (statements, receipts, minutes; O8)
    source         text        NOT NULL DEFAULT 'uploaded' CHECK (source IN ('uploaded', 'generated')),
    -- when the file expires: unattached uploads get a short lifetime that attaching clears
    retention_until timestamptz,
    -- {"thumb": {"width": 256, "height": 171, "size": 9876, "mime": "image/jpeg"}, ...}
    variants       jsonb       NOT NULL DEFAULT '{}',
    created_at     timestamptz NOT NULL DEFAULT now(),
    -- last change of the row (stored, attached, detached, deleted)
    updated_at     timestamptz NOT NULL DEFAULT now(),
    deleted_at     timestamptz,
    -- set once the blobs of a deleted file are gone
    purged_at      timestamptz,
    CONSTRAINT file_org_id_id_key UNIQUE (org_id, id),
    CONSTRAINT file_scope_ck CHECK ((scope_type IS NULL) = (scope_id IS NULL)),
    CONSTRAINT file_ready_hash_ck CHECK (status = 'pending' OR status = 'deleted' OR sha256 IS NOT NULL)
);
CREATE INDEX file_org_scope ON file (org_id, scope_type, scope_id, created_at DESC, id DESC) WHERE scope_id IS NOT NULL AND status <> 'deleted';
CREATE INDEX file_org_uploader ON file (org_id, uploaded_by, created_at DESC, id DESC) WHERE status <> 'deleted';
CREATE INDEX file_org_created ON file (org_id, created_at DESC, id DESC) WHERE status <> 'deleted';
CREATE INDEX file_retention ON file (retention_until) WHERE retention_until IS NOT NULL AND status <> 'deleted';
CREATE INDEX file_to_purge ON file (created_at) WHERE status = 'deleted' AND purged_at IS NULL;
CREATE INDEX file_stale_pending ON file (created_at) WHERE status = 'pending';
SELECT openbekci_enable_rls('file');

-- Bytes stored per organization (originals and variants), for dashboards and
-- quotas. Maintained in the same transactions that add and remove blobs.
CREATE TABLE org_storage_usage (
    org_id     uuid        PRIMARY KEY REFERENCES organization (id),
    bytes      bigint      NOT NULL DEFAULT 0 CHECK (bytes >= 0),
    files      integer     NOT NULL DEFAULT 0 CHECK (files >= 0),
    updated_at timestamptz NOT NULL DEFAULT now()
);
SELECT openbekci_enable_rls('org_storage_usage');

-- +goose Down
DROP TABLE org_storage_usage;
DROP TABLE file;
